UPDATE tblProveedor p SET saldoActualProveedor = (SELECT COALESCE(SUM(c.saldoActualCuentaPorPagar * c.tipoCambioCuentaPorPagar), 0) FROM tblCuentaPorPagar c WHERE c.idProveedor = p.idProveedor AND c.estadoCuentaPorPagar <> 'Anulada'), cargosAcumuladosProveedor = (SELECT COALESCE(SUM(c.montoTotalCuentaPorPagar * c.tipoCambioCuentaPorPagar), 0) FROM tblCuentaPorPagar c WHERE c.idProveedor = p.idProveedor AND c.idConceptoProveedor = @factura AND c.estadoCuentaPorPagar <> 'Anulada'), abonosAcumuladosProveedor = (SELECT COALESCE(SUM((c.montoTotalCuentaPorPagar - c.saldoActualCuentaPorPagar) * c.tipoCambioCuentaPorPagar), 0) FROM tblCuentaPorPagar c WHERE c.idProveedor = p.idProveedor AND c.idConceptoProveedor = @factura AND c.estadoCuentaPorPagar <> 'Anulada'), cargosMesProveedor = (SELECT COALESCE(SUM(c.montoTotalCuentaPorPagar * c.tipoCambioCuentaPorPagar), 0) FROM tblCuentaPorPagar c WHERE c.idProveedor = p.idProveedor AND c.idConceptoProveedor = @factura AND c.estadoCuentaPorPagar <> 'Anulada' AND DATE_FORMAT(c.fechaEmisionCuentaPorPagar, '%Y-%m') = DATE_FORMAT(@fecha_corte, '%Y-%m')), abonosMesProveedor = (SELECT COALESCE(SUM(h.montoPagoProveedor * h.tipoCambioPagoProveedor), 0) FROM tblEncabezadoPagoProveedor h WHERE h.idProveedor = p.idProveedor AND h.estadoPagoProveedor = 'Pagado' AND DATE_FORMAT(h.fechaPagoProveedor, '%Y-%m') = DATE_FORMAT(@fecha_corte, '%Y-%m')) + (SELECT COALESCE(SUM(-c.montoTotalCuentaPorPagar * c.tipoCambioCuentaPorPagar), 0) FROM tblCuentaPorPagar c WHERE c.idProveedor = p.idProveedor AND c.idConceptoProveedor = @credito AND c.estadoCuentaPorPagar <> 'Anulada' AND DATE_FORMAT(c.fechaEmisionCuentaPorPagar, '%Y-%m') = DATE_FORMAT(@fecha_corte, '%Y-%m')) WHERE p.idProveedor = @lg_p3;

UPDATE tblProveedor SET saldoAnteriorProveedor = saldoActualProveedor - cargosMesProveedor + abonosMesProveedor WHERE idProveedor = @lg_p3;

COMMIT;

SELECT @lote AS loteDatosPrueba, 'Carga completada' AS resultado;
